module lounge_planner (input clk,input rst_n,input start,input [2:0] node_count,input [2:0] edge_count,input [2:0] edge_index,input [2:0] edge_a,input [2:0] edge_b,input [1:0] edge_c,input edge_load,output reg [7:0] min_lounges,output reg valid,output reg impossible,output reg loading_done);localparam MAX_NODES=8;localparam MAX_EDGES=20;reg [1:0] state;reg [7:0] current_assignment;reg [2:0] saved_node_count;reg [2:0] saved_edge_count;reg [7:0] edge_a_arr [19:0];reg [2:0] edge_b_arr [19:0];reg [1:0] edge_c_arr [19:0];reg [3:0] min_count;reg found_valid;function automatic [3:0] popcount;input [7:0] val;popcount=(val[7]?8:0)+(val[6]?4:0)+(val[5]?2:0)+(val[4]?1:0)+(val[3]?1:0)+(val[2]?1:0)+(val[1]?1:0)+(val[0]?1:0);endfunctionalways @(posedge clk) begin if (!rst_n) begin state<=0;current_assignment<=0;saved_node_count<=0;saved_edge_count<=0;min_count<=8;found_valid<=0;end else begin case(state) 0: begin if (start) begin state<=1;saved_node_count<=node_count;saved_edge_count<=edge_count;end end 1: begin if (edge_load) begin if (edge_index<saved_edge_count) begin edge_a_arr[edge_index]<=edge_a;edge_b_arr[edge_index]<=edge_b;edge_c_arr[edge_index]<=edge_c;end end if (!edge_load) state<=2; end 2: begin integer valid_all=1;generate for (int i=0;i<MAX_EDGES;i++) begin if (i<saved_edge_count) begin localparam a=edge_a_arr[i],b=edge_b_arr[i],c=edge_c_arr[i];integer node_a=a-1,node_b=b-1;bit bit_a=(current_assignment>>node_a)&1,bit_b=(current_assignment>>node_b)&1;if (c==0) if (bit_a||bit_b) valid_all=0;else if (c==1) if (bit_a==bit_b) valid_all=0;else if (c==2) if (bit_a==0||bit_b==0) valid_all=0;end end end endgenerate if (valid_all) begin [3:0] pop=popcount(current_assignment);if (pop<min_count||min_count==8) min_count<=pop;found_valid<=1;end if (current_assignment<(1<<saved_node_count)-1) current_assignment<=current_assignment+1;else state<=3;end 3: begin if (start) state<=0;end endcase end endendmodule